// Join internal usage records to Stripe invoice records on account_id
// and billing_period, then compute variance_pct per SOP Section 14.1.
// Mirrors reconciliation_engine.calculate_variance()/classify_variance().

const VARIANCE_THRESHOLD_PCT = 0.03;

function round4(n) {
  return Math.round(n * 10000) / 10000;
}

function rootCauseHint(variancePct, ctx) {
  if (ctx.plan_change_mid_cycle && !ctx.proration_applied) {
    return "Plan change mid-cycle not prorated — check subscription upgrade/downgrade timestamp against invoice line item split.";
  }
  if ((ctx.duplicate_event_flag_count || 0) > 0) {
    return `Usage event double-counted — ${ctx.duplicate_event_flag_count} duplicate event IDs detected in metering audit trail.`;
  }
  if (variancePct < 0) {
    return "Metered usage exceeds invoiced amount — possible missed Stripe usage-record submission for this period.";
  }
  return "Unclassified variance — no known heuristic matched; manual investigation required.";
}

const usageItems = $input.all();
const results = [];

for (const item of usageItems) {
  const usage = item.json;
  const invoiced = usage._matched_invoice || { invoiced_overage_units: 0, invoiced_overage_amount_usd: 0 };

  let variancePct;
  if (!usage.metered_api_calls || usage.metered_api_calls === 0) {
    variancePct = invoiced.invoiced_overage_units > 0 ? 1.0 : 0.0;
  } else {
    variancePct = round4((invoiced.invoiced_overage_units - usage.metered_api_calls) / usage.metered_api_calls);
  }

  const requiresReview = Math.abs(variancePct) >= VARIANCE_THRESHOLD_PCT;
  const direction = variancePct < 0 ? "underbilled" : (variancePct > 0 ? "overbilled" : "matched");
  const unitDelta = invoiced.invoiced_overage_units - usage.metered_api_calls;
  const effectiveRate = invoiced.invoiced_overage_units ? (invoiced.invoiced_overage_amount_usd / invoiced.invoiced_overage_units) : 0;
  const estimatedDollarImpact = Math.round(unitDelta * effectiveRate * 100) / 100;

  results.push({
    json: {
      account_id: usage.account_id,
      billing_period_start: usage.billing_period_start,
      billing_period_end: usage.billing_period_end,
      metered_api_calls: usage.metered_api_calls,
      invoiced_overage_units: invoiced.invoiced_overage_units,
      variance_pct: variancePct,
      variance_direction: direction,
      estimated_dollar_impact_usd: estimatedDollarImpact,
      status: requiresReview ? "pending_review" : "auto_resolved",
      root_cause_hint: requiresReview ? rootCauseHint(variancePct, usage) : null,
      run_id: $('Nightly Schedule Trigger (02:00 ET)').first().json.run_id || `recon-${usage.billing_period_end}-01`
    }
  });
}

return results;

// Generate the revrec schedule per subscription: straight-line seat
// recognition (daily) + usage-triggered metered recognition (period-close
// event). Mirrors reconciliation_engine.generate_revrec_schedule().

function toCents(n) {
  return Math.round(n * 100) / 100;
}

const results = [];

for (const item of $input.all()) {
  const sub = item.json;
  const start = new Date(sub.contract_start);
  const end = new Date(sub.contract_end);
  const totalDays = Math.round((end - start) / 86400000) + 1;
  const dailyRate = sub.seat_fee_total_usd / totalDays;

  const seatRecords = [];
  let running = 0;
  for (let i = 0; i < totalDays; i++) {
    const d = new Date(start);
    d.setDate(d.getDate() + i);
    let amount;
    if (i === totalDays - 1) {
      amount = toCents(sub.seat_fee_total_usd - running);
    } else {
      amount = toCents(dailyRate);
    }
    running += amount;
    seatRecords.push({ component: "seat", recognition_date: d.toISOString().slice(0, 10), amount_usd: amount });
  }

  const confirmedUsageUnits = sub.confirmed_usage_units || 0;
  const overageUnits = Math.max(0, confirmedUsageUnits - sub.included_api_calls);
  const usageRecognizedUsd = toCents(overageUnits * sub.overage_rate_per_unit_usd);

  const seatRecognizedTotal = toCents(seatRecords.reduce((a, r) => a + r.amount_usd, 0));
  const totalRecognized = toCents(seatRecognizedTotal + usageRecognizedUsd);
  const deferredBalance = toCents(sub.seat_fee_total_usd - seatRecognizedTotal);

  results.push({
    json: {
      subscription_id: sub.subscription_id,
      cost_center: sub.cost_center,
      as_of: sub.contract_end,
      seat_recognized_usd: seatRecognizedTotal,
      usage_recognized_usd: usageRecognizedUsd,
      total_recognized_usd: totalRecognized,
      deferred_balance_usd: deferredBalance,
      status: "ready_to_post",
      seat_schedule_sample: seatRecords.slice(0, 3),
      subscription_batch_id: `SUB-${sub.contract_end.slice(0,7)}-CC-${sub.cost_center}`
    }
  });
}

return results;

// Build the idempotency key BEFORE constructing the HTTP request, per
// SOP Section 18: key = sha256(subscription_batch_id + ":" + period_end + ":" + je_type)
// This node also builds the balanced QBO Journal Entry payload shape
// (SOP Section 34.4) and embeds the key into PrivateNote since QuickBooks
// Online has no native idempotency-key field (SOP Section 38).

const crypto = require('crypto');

const results = [];

for (const item of $input.all()) {
  const rec = item.json;
  const periodEnd = rec.as_of;
  const jeType = "recognized_revenue_period_close";
  const rawKey = `${rec.subscription_batch_id}:${periodEnd}:${jeType}`;
  const idempotencyKey = crypto.createHash('sha256').update(rawKey).digest('hex');

  const deferredAmount = rec.total_recognized_usd;
  const seatAmount = rec.seat_recognized_usd;
  const usageAmount = rec.usage_recognized_usd;

  const lines = [
    {
      Description: `Deferred revenue release — subscription batch ${rec.subscription_batch_id}`,
      Amount: deferredAmount,
      DetailType: "JournalEntryLineDetail",
      JournalEntryLineDetail: {
        PostingType: "Debit",
        AccountRef: { value: "2400", name: "Deferred Revenue - Subscription" },
        ClassRef: { value: rec.cost_center, name: `Cost Center: ${rec.cost_center}` }
      }
    }
  ];

  if (seatAmount > 0) {
    lines.push({
      Description: `Recognized revenue — seat fee, period ending ${periodEnd}`,
      Amount: seatAmount,
      DetailType: "JournalEntryLineDetail",
      JournalEntryLineDetail: {
        PostingType: "Credit",
        AccountRef: { value: "4100", name: "Recognized Revenue - Seats" },
        ClassRef: { value: rec.cost_center, name: `Cost Center: ${rec.cost_center}` }
      }
    });
  }

  if (usageAmount > 0) {
    lines.push({
      Description: `Recognized revenue — usage overage, period ending ${periodEnd}`,
      Amount: usageAmount,
      DetailType: "JournalEntryLineDetail",
      JournalEntryLineDetail: {
        PostingType: "Credit",
        AccountRef: { value: "4200", name: "Recognized Revenue - Usage" },
        ClassRef: { value: rec.cost_center, name: `Cost Center: ${rec.cost_center}` }
      }
    });
  }

  results.push({
    json: {
      subscription_id: rec.subscription_id,
      cost_center: rec.cost_center,
      idempotency_key: idempotencyKey,
      je_type: jeType,
      qbo_payload: {
        Line: lines,
        TxnDate: periodEnd,
        PrivateNote: `IDEMPOTENCY_KEY:${idempotencyKey} | Batch ${rec.subscription_batch_id}`
      }
    }
  });
}

return results;
